async function signIn(event){event.preventDefault();const form=event.currentTarget,submit=form.querySelector('[type=submit]');submit.disabled=true;const data=Object.fromEntries(new FormData(form));
 // A pasted code or a keyboard suggestion often carries a space; the password is sent exactly as typed.
 for(const name of ['username','code','setupToken'])if(typeof data[name]==='string')data[name]=data[name].trim();
 try{const result=await api(authMode==='join'?'/invites/accept':`/${authMode}`,data);user=result.user;authError='';await db.put('last-user',user);if(result.budgetId)await db.put(`selection:${user.id}`,result.budgetId);await loadHousehold()}
 // A refused sign-in keeps what was typed: only the message changes.
 catch(e){authError=e.message;const shown=form.querySelector('.form-error');if(!user&&form.isConnected&&shown){shown.textContent=authError;submit.disabled=false}else authView()}}
