function entryMarkup(transaction,date){const positive=transaction.amount>=0;return `<li><button class="entry${transaction.disabled?' off':''}" data-action="entry" data-id="${esc(transaction.id)}" data-date="${date}"><span class="entry-icon ${positive?'income':''}" aria-hidden="true">${positive?'↙':'↗'}</span><span class="entry-main"><span class="entry-title">${esc(transaction.description)}</span><span class="entry-sub">${esc(dateLabel(date))}${transaction.category?' · '+esc(transaction.category):''}${transaction.flag===';'?' · <span class="paid">PAID</span>':''}${transaction.disabled?' · Off':''}</span></span><span class="entry-amount ${positive?'income':''}">${esc(money(transaction.amount))}</span></button></li>`}
function todayView(){const now=today(),data=forecast(),current=data.days.find(d=>d.date===now),upcoming=upcomingEntries(data);return `<div class="page-heading"><div><p class="eyebrow">A clear view ahead</p><h1>Your day, at a glance.</h1><p>Plans for today. Confidence for tomorrow.</p></div><span class="date-chip">${esc(dateLabel(now,{month:'short',day:'numeric'}))}</span></div><div class="dashboard-grid"><section class="overview" aria-label="Forecast overview"><div class="balance-card"><p class="eyebrow">Projected closing balance · today</p><div class="balance-amount">${esc(money(current?.closingBalance))}</div><p>A forecast from your budget entries.<br>Check your bank for your actual balance.</p><div class="balance-bottom"><div><span>Lowest in the next 31 days</span><strong class="${data.lowPoint?.balance<0?'low':''}">${esc(money(data.lowPoint?.balance))}</strong></div><span>${data.lowPoint?esc(dateLabel(data.lowPoint.date)):''}</span></div></div><div class="metrics"><div class="metric"><span>Income · next 31 days</span><strong class="income">${esc(money(data.totals.moneyIn))}</strong></div><div class="metric"><span>Expenses · next 31 days</span><strong>${esc(money(data.totals.moneyOut))}</strong></div></div><p class="help">Household time zone: ${esc(state.value.working.timeZone)}.</p></section><section><div class="section-heading"><h2>Coming up</h2>${button('See calendar →','calendar','quiet-button')}</div>${upcoming.length?`<ul class="entry-list">${upcoming.slice(0,12).map(({t,date})=>entryMarkup(t,date)).join('')}</ul>`:'<div class="empty"><strong>A fresh start.</strong>Add your first expense, income, or bill.<br>Your forecast will take shape here.</div>'}</section></div>`}
function calendarView(){const selected=selectedDate>=10000101?selectedDate:today(),s=String(selected),first=Number(s.slice(0,6)+'01'),d=new Date(`${dateInput(first)}T12:00:00Z`),next=new Date(d);next.setUTCMonth(next.getUTCMonth()+1);next.setUTCDate(0);const last=Number(next.toISOString().slice(0,10).replaceAll('-','')),data=forecast(first,last),day=data.days.find(x=>x.date===selected),now=today();return `<div class="page-heading"><div><p class="eyebrow">The bigger picture</p><h1>Your calendar.</h1><p>Tap a day to see what is planned.</p></div></div><div class="panel"><div class="calendar-toolbar"><h2>${esc(dateLabel(first,{month:'long',year:'numeric'}))}</h2><label class="help month-label">Choose month<input id="month-picker" type="month" required value="${dateInput(first).slice(0,7)}" aria-label="Choose month"></label></div><div class="month-grid">${['S','M','T','W','T','F','S'].map(n=>`<span class="weekday">${n}</span>`).join('')}${'<span></span>'.repeat(d.getUTCDay())}${data.days.map(day=>`<button class="day ${day.date===selected?'selected':''} ${day.date===now?'today':''}" data-action="day" data-date="${day.date}" aria-pressed="${day.date===selected}"${day.date===now?' aria-current="date"':''} aria-label="${esc(dateLabel(day.date))}, closing ${esc(money(day.closingBalance))}${day.adjusted?', balance set':''}"><span>${day.date%100}${day.transactions.some(t=>!t.disabled)?' <i class="dot"></i>':''}${day.adjusted?' <i class="balance-mark" aria-hidden="true">◆</i>':''}</span><small>${esc(money(day.closingBalance))}</small></button>`).join('')}</div></div><div class="section-heading"><h2>${esc(dateLabel(selected,{weekday:'long',month:'short',day:'numeric'}))}</h2>${button(day?.adjusted?'Change balance':'Set balance','balance','quiet-button')}</div>${day?.adjusted?`<p class="balance-set"><span aria-hidden="true">◆</span> <strong>Balance set to ${esc(money(day.closingBalance))}.</strong> Later days build from this figure.</p>`:''}${day?.note?`<p class="help">${esc(day.note)}</p>`:''}${day?.transactions.length?`<ul class="entry-list">${day.transactions.map(t=>entryMarkup(t,selected)).join('')}</ul>`:'<div class="empty">No entries planned for this day.</div>'}${button('Add a day note','day-note','quiet-button')}`}
const undoName=record=>{const c=record.changes[0];return c.kind==='payment'?(c.before||c.after).description:`${c.kind==='balance'?'Balance':'Day note'} · ${dateLabel(c.ref)}`};
function undoRow(record){const status=undoStatus(state.value,record.id);return `<div class="activity-row"><div class="row"><strong>${esc(record.summary)}</strong>${status==='ready'?button('Undo','undo','quiet-button',`data-id="${esc(record.id)}"`):''}</div><small>${esc(undoName(record))} · ${esc(new Date(record.at).toLocaleString([],{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}))}</small>${status==='ready'?'':`<small>${esc(status==='undone'?'Undone':undoMessages[status])}</small>`}</div>`}
function undoPanel(){const list=state.value.undo;return list.length?`<div class="panel"><h2>Your recent edits</h2><p>Made on this device. An undo is saved as a new change for the household.</p>${list.map(undoRow).join('')}</div>`:''}
function activityView(){return `<div class="page-heading"><div><p class="eyebrow">A shared picture</p><h1>Household activity.</h1><p>Changes acknowledged by your private service.</p></div>${button('Refresh','refresh-activity','quiet-button')}</div>${undoPanel()}<div class="panel">${history.length?history.map(h=>`<div class="activity-row"><div class="row"><strong>${esc(h.summary||'Budget created')}</strong><span class="badge">v${Number(h.revision)}</span></div><small>${esc(h.author?.username||'Household member')} · ${esc(new Date(h.createdAt).toLocaleString())}</small>${button('Review this snapshot','history-review','quiet-button',`data-revision="${Number(h.revision)}"`)}</div>`).join(''):'<p>No activity loaded yet. Reconnect and refresh to see shared changes.</p>'}</div>${state.value.pending.length?`<div class="panel"><h2>Only on this device</h2><p>${state.value.pending.length} pending change(s). They are saved locally and will appear in shared activity after the service acknowledges them.</p></div>`:''}`}
function settingsView(){return `<div class="page-heading"><div><p class="eyebrow">Make it yours</p><h1>Your household.</h1><p>Private by design. Shared by invitation.</p></div></div><div class="panel"><h2>Account & connection</h2><p>Signed in as <strong>${esc(user.username)}</strong><br>${esc(location.origin)}<br>Role: ${esc(budget.role||'member')}</p>${button('Sync now','sync','secondary')} ${button('Sign in again','reauth','quiet-button')} ${button('Sign out','logout','quiet-button')}<p class="help">Pending changes remain on this device. Signing out does not clear your locally saved budget.</p>${budgets.length>1?`<label>Open household<select id="budget-picker">${budgets.map(b=>`<option value="${esc(b.id)}" ${b.id===budget.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label>`:''}</div><div class="panel"><div class="row"><h2>Members</h2>${button('Refresh','refresh-members','quiet-button')}</div>${members.map(m=>`<div class="member"><span class="avatar member-avatar" aria-hidden="true">${esc(m.username.slice(0,1).toUpperCase())}</span><div><strong>${esc(m.username)}</strong><small>${esc(m.role)}</small></div>${budget.role==='owner'&&m.role!=='owner'?button('Revoke','revoke','quiet-button danger',`data-id="${esc(m.id)}"`):''}</div>`).join('')}${budget.role==='owner'?button('Invite a household member','invite','secondary wide'):''}${button('Accept an invitation','join','quiet-button')}</div><div class="panel"><h2>Passcode, recovery & backups</h2><p>Members unlock this household on a new device with its passcode. Your account password cannot decrypt a budget; the recovery key is the emergency backup if the passcode is lost.</p><div class="stack">${budget.role==='owner'?button(passcodeSet?'Change household passcode':'Set household passcode','passcode','secondary wide'):''}${budget.role==='owner'&&passcodeSet?button('Remove household passcode','passcode-remove','quiet-button danger'):''}${recoveryText?button('Show recovery key','show-key','quiet-button'):''}${button('Export encrypted backup','backup','secondary wide')}${button('Restore encrypted backup','restore','secondary wide')}${button('Export legacy .bgt','export-bgt','secondary wide')}${button('Create another household','create','quiet-button')}</div><p class="help">A backup includes one current local snapshot with pending edits reflected in it. The replay queue and server history are retained separately. Legacy .bgt exports contain readable financial data unless protected elsewhere.</p></div><div class="panel"><h2>On your home screen</h2><p>In Android Chrome, open the browser menu and choose “Add to Home screen” or “Install app”. Open this app once online to cache its calculation engine. ${installPrompt?'An install action is ready below.':''}</p>${installPrompt?button('Install Budget Calendar','install','secondary wide'):''}<p class="help">Browser storage can be cleared or evicted. A local save is not a shared backup; “Synced” means the service acknowledged your changes.</p></div>`}
