function reviewConflict(){const v=state.value;modal('Review both versions',`<p class="lead">Server revision ${v.conflict.revision} was saved while your edits were pending. Neither version has been discarded.</p><details open><summary>Your local version (${v.pending.length} pending changes)</summary><pre>${esc(JSON.stringify(v.working,null,2))}</pre></details><details><summary>Current household version</summary><pre>${esc(JSON.stringify(v.conflict.snapshot,null,2))}</pre></details><p class="help">Reapply repeats your saved commands against the current household. Unrelated remote entries are retained. Where both versions edit the same entry, your reviewed command takes effect. A deleted entry cannot be silently revived.</p><p class="form-error" role="alert"></p><div class="stack">${button('Export my pending work first','backup','secondary wide')}${button('Reapply my edits to current household','reapply','primary wide')}${button('Use household version & discard local edits','discard','quiet-button danger')}</div>`)}
async function reapplyConflict(){const context=captureDocument();try{if(context.state.value.pending.some(p=>p.commands.some(c=>c.replaceSnapshot)))throw Error('A full snapshot restore cannot be merged safely. Export the local version, keep the current household, then review the backup restore again.');const {skipped}=await context.state.reapply(async(snapshot,entry)=>{if(!context.current())throw Error('The active household changed. Reopen conflict review.');const next=engine({action:'apply',snapshot,today:context.today,command:entry.command,operationId:entry.operationId});assertSyncSnapshot(next,context.id);return next});if(!context.current())return;sheet.close();render();notify(skipped.length?'An undo was left out because that entry had changed. Your other edits are saved locally.':'Reviewed edits saved locally · pending sync');void synchronize()}catch(error){if(context.current())sheet.querySelector('.form-error').textContent=error.message}}
function invitation(){modal('Invite a member',`<form><label>Recipient username<input name="recipient" required placeholder="partner@example.com" maxlength="128"></label><p class="help">Use the exact username they will sign in with. The invite expires after 48 hours. No email is sent; share the code yourself, and share the household passcode through a private channel.</p>${footer('Create private invitation')}</form>`,async data=>{const result=await api(`/budgets/${budget.id}/invites`,{recipient:data.get('recipient').trim()});modal('Invitation ready',`<p class="lead">For ${esc(result.invite.recipient)}. Expires ${esc(new Date(result.invite.expiresAt).toLocaleString())}.</p><code class="key">${esc(result.code)}</code><p class="help">This code is displayed once. Share it manually and privately. It does not include the household passcode.</p>${button('Cancel this invitation','cancel-invite','secondary wide',`data-id="${esc(result.invite.id)}"`)}`)})}
async function loadActivity(){const epoch=contextEpoch,accountId=user.id,id=budget.id,result=await api(`/budgets/${id}/history`);if(!activeContext(epoch,accountId)||budget?.id!==id||page!=='activity')return;history=result.history;render()}
async function loadMembers(){const epoch=contextEpoch,accountId=user.id,id=budget.id,result=await api(`/budgets/${id}/members`);let hasPasscode=passcodeSet;try{await api(`/budgets/${id}/passcode`);hasPasscode=true}catch(error){if(error.status===404)hasPasscode=false}
 // A late answer for the household that was open before must not describe the one open now.
 if(!activeContext(epoch,accountId)||budget?.id!==id||page!=='settings')return;passcodeSet=hasPasscode;members=result.members;render()}
async function changePasscodeDialog(){
 if(transitioning||!state||!key)throw Error('Unlock a household before changing its passcode.');
 const context=captureDocument();
 if(!recoveryText){
  await new Promise((resolve,reject)=>{let settled=false;const done=()=>settled=true;modal('Confirm you can unlock this household',`<p class="lead">Changing the passcode re-wraps the household key, so first enter the current passcode or the recovery key.</p><form><label>Current passcode or recovery key<input name="current" type="password" required autocomplete="off"></label><p class="help">This device saved its key without keeping the text.</p>${footer('Continue')}</form>`,async data=>{
   const typed=data.get('current').trim();let text;
   if(typed.startsWith('BC1-')){await importRecoveryKey(typed);text=typed}
   else{const record=await api(`/budgets/${context.id}/passcode`);text=engine({action:'passcode_unwrap',slot:record.slot,passcode:typed,budgetId:context.id}).recoveryKey}
   const candidate=await importRecoveryKey(text);
   // A mistyped current secret must never re-wrap the wrong key over the good slot.
   const remote=await api(`/budgets/${context.id}`);await openSnapshot(remote.payload,candidate,context.id,remote.revision);
   recoveryText=text;done();resolve();
  });sheet.addEventListener('close',()=>{if(!settled)reject(Error('Enter the current passcode or recovery key to continue.'))},{once:true})});
 }
 modal('Set this household\'s passcode',`<p class="lead">Every member uses this passcode to unlock on a new device. It wraps the household key; the recovery key keeps working.</p><form><label>Household passcode<input name="passcode" type="password" required autocomplete="new-password" minlength="8"><small>Three or more unrelated words.</small></label><label>Confirm passcode<input name="confirm" type="password" required autocomplete="new-password" minlength="8"></label>${footer('Save passcode')}</form>`,async data=>{
  const passcode=data.get('passcode').trim();if(passcode.length<8)throw Error('Use at least 8 characters — three or more unrelated words.');if(passcode!==data.get('confirm').trim())throw Error('The two passcodes do not match.');
  const slot=engine({action:'passcode_wrap',recoveryKey:recoveryText,passcode,budgetId:budget.id}).slot;
  await api(`/budgets/${budget.id}/passcode`,{slot},'PUT');
  passcodeSet=true;sheet.close();notify('Household passcode saved. Members can unlock new devices with it.');
 });
}
async function signOut(){if(state?.value.pending.length||state?.value.conflict){modal('Pending work stays on this device',`<p class="lead">Your local changes have not reached the household. Export an encrypted backup before signing out if you need a separate recoverable copy.</p>${isOffline()?'<p class="warning-box" role="status">Signing out needs a connection. Your work stays saved on this phone.</p>':''}<p class="form-error" role="alert"></p><div class="stack">${button('Export pending work','backup','primary wide')}${button('Sign out & keep local work','confirm-logout','secondary wide')}</div>`);return}await finishSignOut()}
async function finishSignOut(){
 const epoch=++contextEpoch,accountId=user.id;transitioning=true;transitionScreen();
 try{try{await api('/logout',{})}catch(error){if(error.status!==401)throw error}if(!activeContext(epoch,accountId))return;await db.remove('last-user');if(!activeContext(epoch,accountId))return;user=null;state=null;budget=null;key=null;history=[];members=[];budgets=[];recoveryText=null;passcodeSet=false;page='today';authMode='login';authError='';selectedDate=undefined;lastSync=undefined;sheet.close()}
 finally{if(contextEpoch===epoch){transitioning=false;render()}}
}
const actions={
 'auth-login':()=>{authMode='login';authError='';authView()},'auth-join':()=>{authMode='join';authError='';authView()},'auth-setup':()=>{authMode='setup';authError='';authView()},
 today:()=>{page='today';render()},calendar:()=>{page='calendar';render()},activity:async()=>{page='activity';render();if(!isOffline())await loadActivity()},settings:async()=>{page='settings';render();if(isOffline())return;await loadMembers()},
 add:()=>editEntry(null,page==='calendar'?(selectedDate||today()):today()),day:element=>{selectedDate=Number(element.dataset.date);render()},entry:element=>entryDetails(element.dataset.id,Number(element.dataset.date)),edit:element=>editEntry(element.dataset.id,Number(element.dataset.date)),delete:element=>deleteEntry(element.dataset.id,Number(element.dataset.date)),move:element=>moveEntry(element.dataset.id,Number(element.dataset.date)),
 paid:async element=>{const date=Number(element.dataset.date),id=element.dataset.id,t=forecast(date,date).days[0].transactions.find(t=>t.id===id);await applyCommand({type:'transaction',id,date,amount:t.amount,note:t.note||'',flag:t.flag===';'?'^':';',scope:'one'},t.flag===';'?'Entry marked unpaid':'Entry marked paid')},
 undo:element=>undoEdit(element.dataset.id),balance:balanceDialog,'remove-balance':async element=>{const date=Number(element.dataset.date);if(confirm(`Remove the balance set for ${dateLabel(date)}? Later days go back to the calculated figures.`))await applyCommand({type:'balance',date,amount:null},'Balance removed')},'day-note':dayNote,create:createBudget,join:joinBudget,sync:async()=>{if(navigator.onLine){syncAsked=true;refreshStatus();try{await synchronize()}finally{syncAsked=false;refreshStatus()}}else notify('You are offline. Your changes will sync when you reconnect.')},backup,restore:restoreDialog,invite:invitation,logout:signOut,'confirm-logout':async()=>{try{await finishSignOut()}catch(e){const shown=sheet.open&&sheet.querySelector('.form-error');if(!(e instanceof OfflineError)||!shown)throw e;shown.textContent=e.message}},
 'refresh-activity':loadActivity,'refresh-members':loadMembers,'history-review':element=>reviewHistory(Number(element.dataset.revision)),passcode:changePasscodeDialog,'passcode-remove':async()=>{if(!confirm('Remove the household passcode? New devices will need the recovery key to unlock.'))return;await api(`/budgets/${budget.id}/passcode`,{},'DELETE');passcodeSet=false;notify('Household passcode removed. Keep the recovery key safe.');render()},'show-key':()=>modal('This household\'s recovery key',`<p class="lead">The emergency backup for this household. Keep it in a password manager; it works even without the passcode.</p><code class="key">${esc(recoveryText)}</code><p class="help">Shown only on a device that unlocked this household. The service never receives it.</p>`),
 'export-bgt':async()=>{const {text}=engine({action:'export',snapshot:state.value.working,today:today()});await download('household-export.bgt',text,'text/plain')},
 'review-conflict':reviewConflict,reapply:reapplyConflict,discard:async()=>{if(!confirm('Discard your pending local edits and use the current household version? Export a backup first if you need to keep them.'))return;await state.discard();sheet.close();render();void synchronize()},
 revoke:async element=>{if(confirm('Revoke this member’s access? Their next server request will be rejected. Previously downloaded information remains on their device.')){await api(`/budgets/${budget.id}/members/${encodeURIComponent(element.dataset.id)}`,{},'DELETE');await loadMembers()}},
 'cancel-invite':async element=>{await api(`/budgets/${budget.id}/invites/${encodeURIComponent(element.dataset.id)}`,{},'DELETE');sheet.close();notify('Invitation cancelled.')},
 reauth:()=>modal('Sign in again',`<form><p class="lead">Renew the session for ${esc(user.username)}. Your pending edits stay on this device.</p><label>Password<input type="password" name="password" required minlength="12" autocomplete="current-password"></label>${footer('Sign in & retry sync')}</form>`,async data=>{await api('/login',{username:user.username,password:data.get('password')});sheet.close();await synchronize()}),
 install:async()=>{await installPrompt.prompt();installPrompt=null;render()}
};
document.addEventListener('click',async event=>{const element=event.target.closest('[data-action]');if(!element)return;const action=actions[element.dataset.action];if(!action)return;element.disabled=true;actionsRunning++;showUpdate();try{await action(element)}catch(e){fail(e)}finally{element.disabled=false;actionsRunning--;showUpdate()}});
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;if(page==='settings')render()});
function refreshToday(){if(writerLease&&!transitioning&&state&&budget&&!sheet.open&&lastRenderedToday!==today())render()}
function tick(){if(document.visibilityState==='visible'){refreshToday();if(Date.now()>=syncRetryAt)void synchronize();refreshStatus();showUpdate();checkForUpdate()}}
window.addEventListener('online',()=>{syncFailures=0;syncRetryAt=0;refreshToday();refreshStatus();if(user&&!state&&!transitioning&&!sheet.open)loadHousehold().catch(fail);else void synchronize()});window.addEventListener('offline',()=>{if(!root.querySelector('#auth-form'))render()});document.addEventListener('visibilitychange',tick);
sheet.addEventListener('close',()=>{refreshToday();showUpdate()});
window.addEventListener('beforeunload',event=>{if(state?.value.pending.length){event.preventDefault();event.returnValue=''}});
setInterval(tick,4000);
async function boot(){try{db=await openStorage();engine=await loadEngine();try{user=(await api('/me')).user;await db.put('last-user',user)}catch(e){if(e instanceof ApiError&&e.status===401)user=null;else user=await db.get('last-user')}if(user)await loadHousehold();else render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').then(watchWorker).catch(()=>notify('Offline installation is unavailable until all app assets are downloaded.'))}catch(e){root.innerHTML=`<main class="auth-shell"><h1>Unable to open Budget Calendar.</h1><p class="lead">${esc(e.message)}</p><p class="help">Your stored budget has not been changed. Reconnect and reload to download the app and calculation engine.</p><button class="primary" id="reload">Reload app</button></main>`;document.querySelector('#reload').onclick=()=>location.reload()}}
let writerLease,writerStarting=false;
async function startWithWriterLock(){
 if(writerLease||writerStarting)return;writerStarting=true;
 try{
  writerLease=await claimWriterLock();
  if(!writerLease){root.innerHTML='<main class="auth-shell"><h1>Budget Calendar is open in another tab.</h1><p class="lead">This tab is paused to protect pending changes saved by the active tab. Close the other Budget Calendar tab before continuing here.</p><button class="primary" id="retry-lock">Retry opening this tab</button></main>';document.querySelector('#retry-lock').onclick=startWithWriterLock;return}
  window.addEventListener('pageshow',event=>{if(event.persisted)location.reload()});
  await boot();
 }catch(error){root.innerHTML=`<main class="auth-shell"><h1>This browser cannot safely open the budget.</h1><p class="lead">${esc(error.message)}</p><p class="help">No budget cache has been opened or changed. Open this address in a browser with Web Locks support.</p></main>`}finally{writerStarting=false}
}
void startWithWriterLock();
